(* [comment removed for export] *)
Lemma rta_phase : forall (t0 t1 a0 a2 a3 a4 a5 a6 a7 : word),
  a0 = Z_to_bv 64 sc ->
  rmrep st m -> mem_inv rsegs m -> stk rsegs m lo spv ->
